"Anyone remember why the sky is a portal?":"Seća li se iko zašto je nebo portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Kažu da ako skočiš u šahtu, izletiš kod neprijatelja. Ne proveravam.",
"The Swarm painted their visors red again. Show-offs.":"Roj je opet obojio vizore u crveno. Pozeri.",
"Ore, ore… when do we get some oil?":"Ruda, ruda… a kad ćemo dobiti ulje?",
"I dreamt I was a toaster. It was peaceful.":"Sanjao sam da sam toster. Bilo je mirno.",
"Quiet. Too quiet.":"Tiho. Previše tiho.",
"See that? Our base is above the Swarm base again. Portals, man.":"Vidiš li? Iznad baze Roja opet visi naša baza. Portali, brate.",
"Diman, if you're reading this — we need a vacation.":"Dimane, ako ovo čitaš — treba nam odmor.",
