"robot war · the sky is a portal":"rat robota · nebo je portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Dobrodošao na meteor! Ti si borbeni robot Konzorcijuma. Gledaj mišem i kreći se tasterima WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: pritisni Shift — skok, drži Shift — let. Energija se obnavlja na tlu.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Pucaj — levi taster miša. Nišan — desni taster miša: preciznije i sa zumom. Ispali nekoliko hitaca.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Punjenje — R. Meci najjače udaraju na srednjoj distanci, 20–50 metara.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Protiv tenkova i zgrada. Ispali raketu.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Gore je zadatak stratega. Trči po zelenim strelicama: na ruti imaš sprint. Zauzmi tačku — stani blizu svetionika.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tvoj odred te pokriva: levo su njihovi portreti i zdravlje. Ako zaostanu, zamoliće te da sačekaš.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — brzo prebacivanje na jedinicu bez izlaska iz borbe: skok u odred ili tenk najbliži borbi. Probaj.",
"Next to a tank or turret press E to take control. Or just carry on.":"Pored tenka ili kupole pritisni E da preuzmeš kontrolu. Ili samo nastavi dalje.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Sada strategija. Dodirni \"◩ Strategija\" gore desno — pogled odozgo na bojište.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Sada strategija. Pritisni {0} (ili \"◩ Strategija\" gore levo) — pogled odozgo na bojište.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"U strategiji ti pomaže Kurator: okvir gore kaže šta da uradiš, ram pokazuje dugme, prsten označava mesto na mapi. Izvrši tri njegova saveta.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Izaberi odred i dodirni zeleno dugme \"▶ Preuzmi kontrolu\" — opet u borbu kao taj vojnik. Dok ti pucaš, AI strateg sam komanduje vojskom.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Izaberi odred i pritisni {0} ili zeleno \"▶ Preuzmi\" — opet u borbu kao taj vojnik (bez izbora — svoj). Dok ti pucaš, AI strateg sam komanduje vojskom.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Obuka je završena! Roj kreće u napad. Srećno, vojniče!",
