"The heavy MG is a reward the strategist hands out for completed orders.":"Teški mitraljez strateg daje kao nagradu za izvršena naređenja.",
"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} se otključava na činu \"{1}\". Iskustvo donose ubistva, zauzimanje tačaka i naređenja stratega (×2–×3).",
"Left thumb — move, right thumb — look. Red button — fire.":"Levi palac — kretanje, desni — pogled. Crveno dugme — paljba.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — džetpek: dodir za skok, drži za let. ◎ — nišan.",
"In the air, ⤓ is the jet brake.":"U vazduhu ⤓ je kočnica džetpeka.",
"Move and shoot: mouse to look, LMB to fire.":"Kreći se i pucaj: miš — pogled, levi taster miša — paljba.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Gore je naređenje AI stratega. Izvrši ga: iskustvo ×2 i ×3, a za izvršena naređenja ima i nagrada. Zeleni marker i strelice vode do cilja.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: dodir za skok, drži za let. Desni taster miša — nišan.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"U vazduhu C je kočnica džetpeka. Zaustavi se, okreni pogledom i daj potisak ponovo.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"U blizini je neprijateljska tehnika ili građevina. Raketa je najbolja protiv njih.",
"Enemies are bunched up — throw a grenade.":"Neprijatelji su se zbili — baci granatu.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Mnogo neprijatelja — uključi refleks: vreme usporava, pa ih možeš pobiti jednog po jednog.",
"Aim at the enemy cluster and call in a strike.":"Naciljaj skup neprijatelja i pozovi udar.",
"Targets are far — the railgun is stronger at long range.":"Ciljevi su daleko — šinski top je jači na velikoj distanci.",
"You have a temporary heavy MG — use it before it is recalled.":"Imaš privremeni teški mitraljez — koristi ga dok ga ne povuku.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkur: C u trku — klizanje, skok kod ivice — penjanje, skok pored zida u vazduhu — odskok od zida.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Meci najjače udaraju na 20–50 m. Iz blizine i izdaleka su znatno slabiji — i za neprijatelje.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Robot je teško oštećen. Skloni se iz vatre — van borbe se oklop sam popravlja.",
"One of our tanks is close. Walk up and press E to take control.":"U blizini je naš tenk. Priđi i pritisni E — upravljaćeš njime.",
"Man the turret — press E next to it.":"Zauzmi kupolu — E pored nje.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Ovde je tiho. Prebaci se na odred ili tehniku bliže borbi.",
"Reload early while no enemies are around.":"Dopuni municiju unapred, dok nema neprijatelja.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Trči pravo po zelenim strelicama stratega — na njegovoj ruti trčiš brže.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Dugme \"◩ Strategija\" — pogled odozgo: gradi bazu, naručuj trupe, komanduj odredima.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Režim strategije: gradi bazu, naručuj trupe, pozivaj udare i komanduj odredima. Isti taster tamo preuzima izabranu jedinicu.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Hoćeš sam da komanduješ? Isključi AI stratega — onda ti izdaješ naređenja.",
"Third-person view — to see your robot.":"Pogled iz trećeg lica — da vidiš svog robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tenk: {0} — plotun u tačku nišana, {1} — dimna zavesa, {2} — forsaž. {3} — nazad u pešadiju.",
"Plenty of targets — fire a barrage.":"Mnogo je meta — ispali plotun.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — gore/dole, levi taster miša — paljba, {2} — udar u tačku nišana.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Izaberi odred — levi taster miša, okvirom ili karticom levo. Desni taster miša po zemlji — napadno kretanje ⚔, po neprijatelju — napad, po tački — zauzimanje.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Odredi imaju sposobnosti: granate, skok džetpekom, suzbijanje, popravka. Tenkovi: plotun, dim, forsaž.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Rude ima dosta — izaberi štab ili fabriku i naruči trupe u njenom panelu desno.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Skupilo se komandnih poena — kartica \"Udari\": izviđanje, artiljerija, desantna kapsula sa odredom, orbitalni udar.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Zgrade grade samo inženjeri: izaberi inženjera (dugme na kartici \"Gradnja\" ili taster zgrade), pa klikni na mesto. Ekstraktor (C) na svetleću žilu — više rude.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klikni na \"RUDA\" gore levo — odakle dolazi ruda i kako ubrzati prihod.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — zapamti grupu, 1…9 — izaberi je, dvostruki pritisak — kamera na nju.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Izaberi jedinicu i dodirni zeleno \"▶ Preuzmi\" dole (ili dupli dodir) — boriš se sam. \"◩ Strategija\" te vraća nazad.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Izaberi jedinicu i pritisni zeleno \"▶ Preuzmi\" dole ili {0} (ili dvoklik) — boriš se sam. U borbi te {1} vraća u strategiju.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Siva dugmad se takođe mogu pritisnuti: pokazaćemo šta nedostaje, koliko čekati i kako to rešiti.",
"RMB on the ground — rally point for this building's new troops.":"DTM po zemlji — mesto okupljanja novih trupa ove zgrade.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"DTM — napadno kretanje ⚔: kad naiđu na neprijatelja, staju i bore se, pa idu dalje. Dvostruki DTM — marš »: trče bez zaustavljanja, pucaju u hodu. Stoj/Povuci se — \"Još naređenja ▾\".",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: vuci prstom, dva prsta — zumiranje i rotacija, i minimapu možeš vući prstom.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD i ivice ekrana, Q/E — rotacija, točkić — zum (ka kursoru), SDM — orbita, minimapa — klik ili prevlačenje, Razmak — do poslednjeg alarma.",
