"New in v6.3":"Novo u v6.3",
"New in v6.2":"Novo u v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Novi izgled rude: žile su sjajni smaragdni brušeni kristali na crnom bazaltu sa varnicama i zelenom izmaglicom; ekstraktor je šestougaoni postolje sa saćastom kupolom i rešetkastim tornjem sa zelenim svetionikom (traka i zastavica — boja tima)",
"New in v6.1":"Novo u v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Omiljena klasa kao u Battlefieldu (U, brojevi posle pogibije): vraćaš se u nju kad je dostupna",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Tehnika iz prvog lica (V — spolja/iz kabine); blago automatsko ciljanje — u Podešavanjima",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Lako izlaženje iz jezgra: Razmak — do okna, B — kapsula na površinu; efekti sposobnosti se resetuju pri pogibiji",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Beskonačno napredovanje: generali i Maršal ★, nivoi karijere, majstorstvo oružja i dodaci, medalje, dnevni ugovori — ekran „Karijera\"",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategija: glatki zum točkićem, ikonice i oznake iznad jedinica (Alt — sve), panel „Trupe / Zgrade\" levo",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"DTM — idi i bori se usput, 2× DTM — marš uz paljbu u hodu; retke naredbe su u „Još naredbi ▾\"; dugmad se ne dupliraju",
"New in v6":"Novo u v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Pucanje kao u pravim strelcima: trenutni meci, automat 720 metaka/min, mitraljez, trzaj, nišan na DTM, šaržeri i punjenje na R, oznake pogodaka",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Teža gravitacija, odzivan džetpek, poskok na Z ili 2× džetpek u vazduhu; oružje više ne leti za tobom pri prelasku u drugog borca",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inženjeri: izaberi inženjera, izaberi zgradu, postavi nacrt; ekstraktori na rudnim žilama; klik na „RUDA\" — odakle je prihod i kako ga ubrzati",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Sive dugmad objašnjavaju zašto ne rade i nude rešenje; krupnija dugmad, traka „U radu\", „▶ Preuzmi\", Tab — jedan taster za mod",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera strategije bez trzaja i preokretanja, zum ka kursoru, minimapu možeš da vučeš",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nova tehnika: „Šakal\" (rejder), raketni bacač „Grad\" (rakete samonavođenja), minobacač „Malj\"; Roj dobija „Osu\", „Košnicu\", „Katapult\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI strateg ne menja naredbe i ne zatrpava glasom; borbe su blizu tebe; B — prebacivanje, Shift+B — u središte borbe; kompas, H — koja meta",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Sloboda delovanja (K) i „delujem sam\" (J), F2 — podešavanja unapred; Esc — pauza i nazad; čuvanje: slotovi, izvoz i uvoz fajla",
"New in v5.3":"Novo u v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Let: gravitacija je jača daleko od meteora, C u vazduhu — kočnica, potisak oštrije upravlja; više ne „visiš\" u portalu",
"New in v5":"Novo u v5",
"Endless war by default and battle scale: normal, large, epic":"Beskonačan rat podrazumevano i razmera borbi: obična, velika, epska",
"Save and load the battle (autosave every 3 minutes)":"Čuvanje i učitavanje borbe (i automatsko čuvanje svaka 3 minuta)",
"Squadmates with callsigns: portraits, health and live chatter":"Odred sa pozivnim znacima: portreti, zdravlje i žive radio-prepiske",
"Fog of war in strategy, friends and foes outlined differently":"Magla rata u strategiji, saveznici i neprijatelji istaknuti različito",
"Camera fly-over when switching, portal aurora instead of rings":"Preletanje kamere pri prebacivanju, sjaj portala umesto prstenova",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Sporedni zadaci, prečica kroz nebo, moduli prve ekspedicije sa zalihama, kristali, led u kraterima, prašnjave oluje",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Obuka, filmski mod sa snimanjem klipova, pratnja vozilima od AI stratega",
