"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Model prati normalu površine meteora, okreće trup prema cilju i drži mitraljez; izdaleka se animacija ređe osvežava radi FPS-a",
