"HQ: {0} online":"Štab: {0} u funkciji",
"Intel: the Swarm HQ got \"{0}\"":"Izviđanje: štab Roja je dobio „{0}\"",
"Point {0}: orbit is dropping a pod — a squad{1}":"Tačka {0}: orbita spušta kapsulu — odred{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapsula na tački {0}: {1}{2}{3}. Graditelj može da postavi predstražu (V) i izabere granu poboljšanja.",
"HQ radar: every enemy is visible for 6 s":"Radar štaba: svi neprijatelji vidljivi 6 s",
"HQ upgrades":"Poboljšanja štaba",
"Built":"Izgrađeno",
"Building — click to cancel (refund)":"Gradi se — klik: otkaži (ruda se vraća)",
"Outpost upgrades":"Poboljšanja predstraže",
"point":"tačka",
"Pick a branch — every point gets its own speciality:":"Izaberi granu — svaka tačka ima svoju specijalizaciju:",
"Building — click to cancel":"Gradi se — klik: otkaži",
"A builder near the outpost (30 m) does the upgrade.":"Poboljšanje gradi inženjer pored predstraže (30 m).",
"Send a builder":"Pošalji inženjera",
"Builders nearby":"Inženjera u blizini",
"{0} is heading to the outpost":"{0} ide ka predstraži",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Od samog početka borbe na bazi stoji cela vojska po jedan: vojnici, mitraljezac-pojedinac, snajperista, izviđač, dron, „Šakal\", raketna artiljerija, minobacač (i jurišni odredi sa tenkom) — preuzmi bilo koga odmah",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"„Sopstveni redosled\" preuzimanja (pauza, na telefonu ☰): svaka klasa ima broj, 1 je glavni; ▲▼ menjaju, ✕ — nikad. Posle pogibije i na X uzima se borac najbliži borbi po tom redosledu",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Botovi više nisu snajperisti: promašuju izdaleka, u trku, trkače i one u zaklonu; pored tebe meci zvižde, udaraju u zemlju i zaklon. Eksplozije obaraju s nogu: trzaj, na koleno, s nogu i ustajanje",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Zauzmi tačku i stiže kapsula sa četom i inženjerom. Predstraža na tački se unapređuje duž jedne grane: odbrana (bunker → bunker sa PT topom), podrška (popravni dronovi → silovna kupola), izviđanje (radio skener → snajperska osmatračnica)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Štab se takođe unapređuje: oklopne ploče, kupole, ubrzano orbitalno spuštanje, prihod +25 %, globalni radar, komunikacione antene (+komandni poeni). AI radi isto",
"New in v7.0":"Novo u v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"Na bazi je po jedan borac i vozilo svakog tipa: vojnici, snajperista, izviđač, dron, „Šakal\", raketna artiljerija, minobacač. Izaberi bilo koga i {0} — probaj pre nego što počneš da gradiš.",
"POSSESS":"PREUZMI",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Tačka {0}: iz kapsule se iskrcao inženjer. Izaberi ga i postavi „Predstražu\"{1} kod tačke — posle biraš granu poboljšanja.",
"OUTPOST":"PREDSTRAŽA",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Predstraža je gotova — izaberi je i izaberi granu: ⛨ Odbrana (bunker, bunker sa PT topom), ✚ Podrška (popravni dronovi, silovna kupola) ili ◎ Izviđanje (skener, snajperska osmatračnica). Gradi inženjer u blizini.",
"UPGRADE":"UNAPREDI",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Štab je „super-tačka\": izaberi ga{0} — oklopne ploče, kupole, ubrzano spuštanje, prihod +25 %, radar, antene.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → „Preuzimanje\": uključi „Sopstveni redosled\" i odluči koga preuzimaš posle pogibije — №1, №2… ✕ — nikad.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → pauza → „Sopstveni redosled\": odluči koga preuzimaš posle pogibije i na X — №1, №2… ✕ — nikad.",
