"The Polygon works in developer mode only":"Poligon radi samo u režimu programera",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Poligon: borba u centru mape, pojačanja bez kraja. X — preuzmi vojnika na poligonu",
