"training complete":"obuka završena",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Dodirni „Nišan\" — zum. Još dodir — nazad.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Odred ide za tobom. Otvori ☰ → „Pauza\" → pločica „Odred sa mnom\" — postaće „Delujem sam\".",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inženjer je izabran — dodirni „◆ Vadi kristale\" na njegovoj kartici dole (ili dodirni zelene kristale).",
"Training complete!":"Obuka završena!",
"steps":"koraka",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Umeš da gradiš bazu, naručuješ trupe, komanduješ i skačeš u borbu. Dalje — pravi meč: Vodič će te savetovati tokom igre.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Umeš da se krećeš, letiš, pucaš, kriješ se i komanduješ odredom. Dalje — pravi meč.",
"Real battle":"Prava borba",
"Again":"Još jednom",
"done":"završeno",
"you are on PC: keyboard and mouse":"ti si na PC-ju: tastatura i miš",
"you are on a phone: touch screen":"ti si na telefonu: ekran osetljiv na dodir",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Bezbedna peščanica: neprijatelji su nepokretni manekeni, niko ne puca na tebe. Korak se računa tek kad sam izvedeš radnju.",
"Show others (training for the other device)":"Prikaži ostala (obuke za drugi uređaj)",
"Old training (v7.1)":"Stara obuka (v7.1)",
"Back to the normal device mode":"Vrati običan režim uređaja",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Obuka za drugi uređaj ponovo učitava stranicu u njegovom režimu (PC — miš i tastatura, telefon — dodir; na PC-ju dodir lako testiraš u Chrome-u: F12 → ikonica telefona).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Obuka ×4: zasebne obuke korak po korak „Strategija\" i „Strelac\" za PC i za telefon. Bezbedan poligon sa lutkama, istaknuto pravo dugme, strelice, animirani tasteri, miš i pokreti; korak se računa samo za pravu radnju, „ponovi korak\", napredak na vrhu i nagrada na kraju",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Meni „Obuka\" sam prikazuje obuke za tvoj uređaj; „Prikaži ostala\" — sve četiri na bilo kom uređaju; „Stara obuka (v7.1)\" je ostala",
"New in v7.2":"Novo u v7.2",
"NEW IN v7.2":"NOVO U v7.2",
"No grenades left":"Nema više granata",
"Rocket and grenade recharging · {0} s":"Raketa i granata se pune · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Levo — kretanje, desno — pogled · dodir na neprijatelja — raketa / granata · 2 dodira — refleks · 3 dodira — artiljerijski udar",
"Less":"Manje",
"More":"Više",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Neprijateljsko vozilo ili objekat u blizini — dodirni ga: poleteće raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Mnogo neprijatelja — brzo dodirni 2 puta slobodno mesto desno: refleks usporava vreme.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Nanišani skup neprijatelja i dodirni 3 puta — artiljerijski udar.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Levi palac — kretanje, desni — pogled. Kad je nišan na neprijatelju, pucanje je automatsko.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ levo uz ivicu — džetpek: dodir za skok, drži za let.",
"Old v7.2 layout":"Stari raspored v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Prevuci prstom po desnoj polovini ekrana — ispod prsta se pojavljuje džojstik pogleda.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dodirni levu stranu i prevlači prstom — ispod prsta se pojavljuje džojstik. Stigni do zelene oznake.",
"Hold the \"Jet\" button at the left edge.":"Drži dugme „Džetpek\" uz levu ivicu.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Desnim džojstikom nanišani lutku — vojnik puca sam kad je nišan na meti.",
"Tap the dummy on the screen — a rocket flies.":"Dodirni lutku na ekranu — poleteće raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Dodirni lutku — poletiće granata (u metu, u luku).",
"Double tap an empty spot on the right quickly.":"Brzo dodirni 2 puta slobodno mesto desno.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lagani režim za slabe telefone: manja rezolucija, bez senki i izobličenja, duplo manje botova i čestica, ograničenje na 30 FPS; sam smanjuje rezoluciju ako je FPS < 25. Na telefonu je podrazumevano uključen (Podešavanja → Grafika → „Lagani režim\"; ili ?lite=1 / ?lite=0 u linku).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: novi raspored kontrola. Levo — kretanje, desno — pogled (oba džojstika se pojavljuju ispod prsta). Samo levi prst — „auto\"; kad je desni u igri, vojnik puca sam samo dok je nišan na neprijatelju. Dodir na neprijatelja — raketa ili granata, 2 dodira — refleks, 3 dodira — artiljerijski udar. Automatsko punjenje. Džetpek — dugme uz levu ivicu. Donji uglovi su slobodni, mini-mapa u uglu, savete možeš zatvoriti krstićem, zadatak možeš da sklopiš. Stari raspored: Podešavanja → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Saveti (iskačući i Vodič) — jedan prekidač u podešavanjima. Ko si ti (tip vojnika ili vozila) — oznaka „Ti: …\" u HUD-u. Optike puške i mitraljeza su providne. Panel „Arsenal\" je zakačen desno, može da se sklopi i isključi. Režim „sam bez odreda\" (J) je uklonjen. Glas stratega više ne ponavlja istu repliku. Tenkovi dobijaju indikator kupole u odnosu na trup. Kursor više ne nestaje na početku obuke strategije.",
