"Voice of hints and curator":"Glas saveta i Vodiča",
"Advanced: custom class order":"Napredno: sopstveni redosled klasa",
"Voice of hints & curator":"Glas saveta i Vodiča",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: tri režima džojstika. Samo levi — „auto\" (jak magnet, slabiji meci). Samo desni — nišan se uključuje sam, jači magnet, preciznije pucanje. Oba odjednom — bez nišana, slabiji magnet i preciznost. Dugme 👁 desno sakriva/vraća interfejs.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Телефон: strategija je pojednostavljena — samo inženjer i zgrade. Kartice levo (inženjer, štab, kasarna…): dodir — kamera odleti tamo, dole se vidi šta graditi/proizvoditi. „U borbu\" — gore levo. Vojska se bori sama. Puna strategija — Podešavanja → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Preuzimanje — dve kvačice: „Odredi\" i „Vozila\" (na telefonu su vozila podrazumevano isključena — vozi ih AI). Kad su vozila isključena, E (na telefonu — dugme desno) pored svog vozila — sedi za njegov top: vozilo vozi samo, ti pucaš. Stari „sopstveni redosled klasa\" je u „Naprednim\". Pri preuzimanju jedinica se javlja preko radija.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Pametni saveti: osnovni se sami gase posle 2. pokretanja, ali će te igra upozoriti na funkciju koju nikad ne koristiš. Prekidači: osnovni / napredni / retki, zasebno — glas saveta i Kuratora.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks se puni od ubistava (serija — jače). Saborci su zaostali ili poginuli — strateg ti spušta nove (skuplje od običnog pojačanja). Grafika i zvuk v7.2gfx su ubačeni: eksplozije u oblacima, dim, krhotine, akustika okana i kratera. Datum izdanja je sada pravi.",
