"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karijera i snimanja ostaju netaknuti. U borbi je isti meni dugme „🛠 Meni\" gore desno{0}.",
"New developer match":"Novi meč programera",
"all unlocked, endless ore, instant build, arsenal":"sve otključano, ruda bez kraja, trenutna gradnja, arsenal",
"Trainings — all 4":"Obuke — sve 4",
"PC and phone (strategy and shooter)":"PC i telefon (strategija i strelac)",
"Cinema: split screen":"Bioskop: podeljen ekran",
"strategist bot left, shooter bot right":"levo bot-strateg, desno bot-strelac",
"Cinema: everything built":"Bioskop: sve izgrađeno",
"both bases built and upgraded — for footage":"obe baze izgrađene i unapređene — za snimanje",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Bioskop režim — podeljen ekran: levo bot-strateg (pogled odozgo na bazu i armiju), desno bot-strelac iz prvog lica. Dugmad dole (i tasteri S, P): „Podeljen ekran\" i „★ Sve izgrađeno\" — obe baze izgrađene i unapređene za snimanje.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Jezgra i tunela kroz meteor više nema — meteor je pun, borba se vodi samo na površini.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 sakriva interfejs, ali zadržava jetpack, ⇆, stikove i marker zadatka. „◎ Nišan\" (samo desni prst) — osetno jači i širi magnet; jačina magneta za sva tri režima — Podešavanja → Kontrole → „Napredno\". Kod topa vozila dugme se zove „Siđi\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Obuka: na telefonu samo telefonske, na PC-ju samo PC. Sve 4 su u meniju „🛠 Programer\". Režim programera i Arsenal su sada jedan meni (u borbi — „🛠 Meni\" gore desno, na PC-ju i F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Stilovi grafike „Dendy (8-bit)\" i „16-bit\": Podešavanja → Grafika → „Stil grafike\" (detalji — dugme ⚙). Ako je FPS u prvih ~10 s meča ispod 24, Dendy se uključuje sam (ispod 20 — još krupniji piksel, 120 linija); traka „vrati uobičajeno\" trajno vraća običnu grafiku. Tvoj izbor u meniju uvek ima prednost.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D modeli okruženja (ruševine, tehnika, utvrđenja) — samo oni sa dobrim ocenama, učitavaju se po potrebi sa interneta. Isključivanje: Podešavanja → Grafika → „Novi 3D modeli okruženja\".",
"New in v7.5":"Novo u v7.5",
"NEW IN v7.5":"NOVO U v7.5",
"Built by the squad: {0}":"Izgrađeno rukama odreda: {0}",
"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"Vojniče, inženjeri su zauzeti — pomozi da se završi: {0}, {1} m. {2} kod gradilišta.",
"Strategist order: finish the {0} ({1} m)":"Naređenje stratega: dovrši {0} ({1} m)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Strateg: oznaka ⌖ na skupu neprijatelja, {0} m — artiljerijski udar za 8 sekundi. Ne prilazi!",
