"stop building":"prestani da gradiš",
"cache: take the weapons":"skrovište: uzmi oružje",
"Building: {0} — stay close":"Gradiš: {0} — stoj blizu",
"Prone / stand up (crawl)":"Lezi / ustani (puzanje)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Gradnja vojnicima: E (na telefonu „Uđi\") kod svog gradilišta — vojnik gradi sam, drugovi iz odreda u blizini pomažu. Ako su inženjeri zauzeti, strateg sam traži pomoć — oznaka „GRADILIŠTE\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Oznake stratega: strateg stavlja ⌖ na skupinu neprijatelja pored tebe — za 8 s tamo udara artiljerija, a svoje RSZO „Grad\" u blizini daju plotun. Tvoj artiljerijski udar iz strategije takođe dobija podršku „Gradova\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrovišta sa oružjem u teretnim kontejnerima i srušenim satelitima (📦 se vidi sa 70 m): E — teški mitraljez na 90 s, zapaljivi meci ili rakete, plus pune granate. Puzanje: Ctrl — lezi / ustani (niže, preciznije, ali sporo).",
"Anonymous statistics":"Anonimna statistika",
