"Link copied":"Link kopiran",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Igraj odmah\" — prvo dugme menija: kratak prelet pod nebom-portalom i odmah u borbu (preskakanje — bilo koji taster ili dodir).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Pogoci se osećaju: metalni zvuk i varnice, oznaka ubistva kod nišana (u glavu — žuta), serija ×N, blago drhtanje od eksplozija, slou-mo na važnim ubistvima. Drhtanje, slou-mo i savet mogu se isključiti u Podešavanjima.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Rezultat meča: vreme, ubistva, najbolja serija, ★ MVP i najbolja četa, kartica meča — „⇪ Podeli\", PNG ili link ka igri.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Savet „šta sad raditi\" levo ispod resursa: naređenje stratega, tačka za zauzimanje, napad Roja. ✕ ili F7 — sakrij.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Borba se sama čuva ako zatvoriš ili minimizuješ karticu — „⟲ Nastavi\" u meniju.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Verzija v7.5 je ostala u meniju „🕘 Verzija igre\" — ako ti se nova ne svidi. Anonimna statistika (bez imena i pošte) se sada šalje; isključuje se u Podešavanjima.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Igraj odmah\", odziv pogodaka, rezultat meča sa karticom, savet „šta raditi\", automatsko čuvanje",
"and older: v7.5, v7.4, milestones v1–v7.0":"i starije: v7.5, v7.4, prekretnice v1–v7.0",
"New in v7.6":"Novo u v7.6",
"NEW IN v7.6":"NOVO U v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Izbor frakcije pred meč: „Konzorcijum\" (teška pešadija u energetskom oklopu, oklop i artiljerija) ili „Roj\" (brzina, čoporovi dronova, teški hici sa distorzijom). AI igra za drugu. Izbor se pamti.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Svaka frakcija ima svoju tehniku i jedinstvene stvari: Konzorcijum — tenk „Nosorog\" i „Keramitne ploče\", Roj — „Čopor dronova\" i „Fazni džetpekovi\". Balans je proveren mečevima botova.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Krateri od eksplozija: artiljerija, rakete i tenkovski topovi kopaju jame u meteoru — kroz njih se hoda i vozi, a u njima možeš da se skloniš.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pogled iz 3. lica za vojnika (V, pamti se; na telefonu — Kontrole) i glatka kamera vozila sa oznakom gde će pogoditi top.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Verzija v7.6 ostala je u meniju „🕘 Verzija igre\" — ako ti se nova ne dopadne.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcije Konzorcijum / Roj sa izborom pre meča, krateri od eksplozija, pogled iz 3. lica",
"and older: v7.6, v7.5, milestones v1–v7.0":"i starije: v7.6, v7.5, prekretnice v1–v7.0",
