"Anomaly ahead! The vein is singing — go around!":"Anomalija ispred! Žila peva — zaobilazimo!",
"Hear that hum? A singing vein. Keep clear!":"Čujete li taj huk? Pevajuća žila. Ne prilazite!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalija! Vazduh se vrtloži — to je vir, zaobiđi ga!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kamenje lebdi u vazduhu… Vir! Ne prilazi!",
"Anomaly ahead — it is crackling with current!":"Anomalija ispred — pucketa strujom!",
"Rods and lightning — a Crackler. It loves armour!":"Šipke i munje — Pucketač. Voli oklop!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalija! Tlo podrhtava od žege — Žarište!",
"Careful, a Brazier underfoot!":"Pažnja, ispod nogu je Žarište!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalija — zelena magla! Kiselina, zadržite dah!",
"The mist is drifting our way, go around!":"Magla puzi ka nama, zaobilazimo!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalija! Vazduh je kao staklo — Sočivo, krivi metke!",
"Everything is warping… a Lens nearby!":"Slika se talasa… Sočivo je blizu!",
"Ha! An enemy walked right into the anomaly!":"Ha! Neprijatelj je ušetao pravo u anomaliju!",
"Got him! Lure them into anomalies!":"Upao je! Namami ih u anomalije!",
"Beautiful zap! One less tin can.":"Lepo je sijevnulo! Jedna limenka manje.",
"The anomaly got me!":"Anomalija me je zahvatila!",
