"They say veins hide artifacts. Only first the vein sings…":"Kažu da u žilama kriju artefakte. Samo što prvo žila peva…",
"Throw a bolt first, then walk. Old habit.":"Prvo baci šraf, pa tek onda idi. Stara navika.",
