" — close":" — zatvori",
"Supply drop":"Sanduk snabdevanja",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Spušta sanduk pored vaših snaga: municija, granate, rakete, delovi oružja, komplet za popravku.",
"\"Grad\" rocket strike":"Udar „Grada\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raketa po velikoj površini za 3 sekunde — brže i šire od artiljerijskog udara.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Podrška: sanduk, izviđanje, „Grad\", artiljerijski udar (zatim 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"PAŽNJA: „Grad\" Roja po vašem rejonu!",
"Warning! Rocket salvo on our position!":"Pažnja! Raketni plotun na našu poziciju!",
"take the supply crate":"uzmi sanduk snabdevanja",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalije na meteoru (talas 1): „Pevajuća žila\" — svetleći zeleni kristal koji huči i ritmičnim impulsima udara sve u blizini; „Vir\" vuče i šutira, „Pucketač\" seva munjama između šipki, „Žarište\" bukne pod nogama, a „Kisela magla\" i „Sočivo\" (krivi metke i sliku) lutaju okolo.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalije se osećaju unapred (huk, sjaj, treperenje). Isprazni ih granatom, raketom ili šrafom (E kod anomalije): zaspaće, a ponekad ostavi artefakt sa plusom i minusom. Odred upozorava preko radija, a neprijatelji (i svoji) ponekad upadnu u njih — namami ih!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Podrška za komandne poene (KP): 4 u borbi (📡 na telefonu) — sanduk snabdevanja, izviđanje, udar „Grada\", artiljerijski udar po nišanu. Strateg na mapi vidi anomalije tek posle izviđanja.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Sanduci snabdevanja u ruševinama starih ekspedicija, kod štabova i pored sagrađenih zgrada: municija, granate, rakete, delovi oružja (otključavaju dodatke).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Verzija v7.7 ostala je u meniju „🕘 Verzija igre\". Anomalije se mogu isključiti u Podešavanjima.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalije („Pevajuća žila\" i još 5), pražnjenje šrafom i granatom, artefakti, podrška za KP, sanduci snabdevanja",
"and older: v7.7, v7.6, milestones v1–v7.0":"i starije: v7.7, v7.6, prekretnice v1–v7.0",
"New in v7.8":"Novo u v7.8",
"NEW IN v7.8":"NOVO U v7.8",
"Close":"Zatvori",
"Anomalies on the meteor":"Anomalije na meteoru",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ u uglu otvara meni pauze: Nastavi, Počni ispočetka, Obuka, Grafika, Podešavanja, Glavni meni (uz potvrdu). Telefon: ☰ gore desno (akcije u borbi — pločica „⚡ Akcije\"); PC: dugme „☰ Meni\" gore desno ili Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika je podrazumevano uvek obična — Dendy samo po tvom izboru: prekidač „Grafika: Obična / Dendy (8-bit) / 16-bit\" je pravo u glavnom meniju i meniju pauze. Ako igra jako koči, pojaviće se savet sa dugmetom „Uključi Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon i tablet: dugme akcije „✋\" desno pojavljuje se samo kad u blizini ima nešto da se uradi — „Uzmi\" (skrovište, sanduk), „Uđi\" (vozilo, kupola, top), „Gradi\", „Siđi\", „Šraf\" kod anomalije. Možeš i samo da dodirneš istaknuti predmet.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategija: drži prst ~0,3 s (telefon zavibrira, pojaviće se žuti prsten) i vuci — okvir za selekciju; običan potez prstom pomera kameru. Postoji i dugme „Okvir\" desno; u obuci korak „Okvir\" priznaje i izbor odreda dodirom.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: sitna dugmad se lakše pogađaju, lista podrške 📡 je veća, paneli strategije više ne prekrivaju pauzu i rezultate. Verzija v7.8 ostala je u meniju „🕘 Verzija igre\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Meni ☰ na telefonu i PC-ju, bez auto-Dendyja, dugme „✋\" na telefonu, okvir selekcije na telefonu",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Koči? Probaj Dendy grafiku — lakša je.",
