"Pause: resume, restart, training, graphics, settings, main menu":"Pauza: nastavi, ispočetka, obuka, grafika, podešavanja, glavni meni",
"Menu: pause, restart, training, graphics, settings":"Meni: pauza, ispočetka, obuka, grafika, podešavanja",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Drži prst na tlu ~0,3 s — telefon zavibrira i pojaviće se žuti prsten — pa, ne puštajući, vuci: dobićeš okvir. Ili dugme „Okvir\" desno. Može i samo dodir na odred.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Za pun ekran na iPhone-u: „Podeli\" ⬆ → „Dodaj na početni ekran\" — igra će se otvoriti bez Safari traka.",
"Open portal-meteor.pages.dev for that.":"Za to otvori sajt portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Dodir — izaberi · dodir na tlo — idi · drži — meni naredbi · drži i vuci — okvir · 2 prsta — zumiranje",
"Robo-ninja":"Robo-ninđa",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Heroina-ubica: trzaji-teleporti, katana, shurikeni. Sama skače po neprijateljskim zonama i seče robote. 1 po strani.",
"Shadow protocol":"Protokol „Senka\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Istraživanje: otključava robo-ninđu u Kasarni. Potrebna je završena Fabrika mehova.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Heroina (1 po strani): sama se teleportuje po neprijateljskim zonama i seče robote; možeš da je preuzmeš i igraš ručno.",
"is ready. She works on her own (AUTO) — possess her to play manually":"je spremna. Radi sama (AUTO) — preuzmi je da igraš ručno",
