"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUEL NINĐI! Blok pred udarac je odbijanje, trzaj je izmicanje. Prati blesak zamaha",
"The two ninjas have met in a duel!":"Dve ninđe su se sukobile u duelu!",
