"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sama skače po neprijateljskim zonama i seče. Džojstik / WASD — pauza 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ručno: dodir na neprijatelja — trzaj i udarac, prevlačenje — zamah, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ručno upravljanje: LMB — katana, RMB — blok, Shift — trzaj, Q — shurikeni, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninđa: dodir na neprijatelja — nalet i udarac, prevlačenje desno — zamah, ● — udarac, 🛡 — blok (na vreme = pariranje), ⇑ — skok u stranu, ✦ — šurikeni, ◎ — teleport, AUTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninđa: LTM — katana (drži — težak udarac), DTM — blok (na vreme = pariranje), Shift/Z — skok u stranu, Q — šurikeni, G — teleport do nišana, skok u vazduhu — dupli skok / trčanje po zidu, {0} — AUTO",
