"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: 100+ numera EDMITRY-ja direktno u igri — dugme 📻 (PC: taster 5, [ ] — numera). Muzika se učitava preko mreže i ne opterećuje igru; jačina i automatsko pokretanje su u Podešavanjima, plus link „Slušaj na Spotify-ju\".",
