"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 desno — Radio Portal Meteor: muzika EDMITRY-ja dok se boriš.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor: muzika EDMITRY-ja dok se boriš. [ ] — numera.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): jačina",
"Radio: start by itself in battle":"Radio: samo se uključuje u borbi",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: kiborg sa katanom. Otključava se u Kasarni istraživanjem „Protokol Senka“ (potrebna fabrika mehova). Sama se teleportuje u neprijateljske zone, seče neprijatelje na delove (bez krvi — varnice), skokovi u stranu, šurikeni, dueli sa neprijateljskom ninđom. Preuzmi je — režim AUTO ili ručno upravljanje (na telefonu — sopstvena dugmad).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 numere EDMITRY-ja direktno u igri. Taster 5 (može se promeniti), na telefonu — ☰ → Podešavanja → Zvuk. Jačina i „samo se uključuje u borbi\" su u podešavanjima; muzika utihne tokom eksplozija i radio-glasa.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Novi jezici: uzbečki i tadžički — potpuno; kineski, španski, portugalski — delimično. Novi izbor jezika u meniju pored „Novi meč\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: „sakrij ikone\" 👁 skuplja preostala dugmad u uredan stub uz desnu ivicu; portret se više ne preklapa; iPhone — igra se ne sukobljava sa Safari pokretima, a „Podeli → Dodaj na početni ekran\" pokreće je preko celog ekrana.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Iz v7.8.1: ☰ meni u uglu (pauza, ponovo, obuka, grafika), bez automatskog Dendy-ja, dugme radnje ✋ na telefonu. v7.8.1 i v7.8 ostaju u meniju „🕘 Verzija igre\".",
