"SABOTAGE":"DIVERZIJA",
"Living world: requests, hero quests, breakthrough ops":"Živi svet: molbe svojih, zadaci heroja, preokret borbe",
"Living world":"Živi svet",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Svoji traže pomoć i nagrađuju, heroji daju zadatke, zaglavljeni front se lomi operacijom",
"A request":"Molba svojih",
"Breakthrough":"Preokret borbe",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Svoji ponekad traže pomoć: glas preko radija, kartica „MOLBA\" i oznaka ✋. Odred je pritisnut — uništi neprijatelje kraj njega. Nagrada: vojnik kapsulom sa baze, top iz gepeka bagija, mesto strelca ili orbitalno pokrivanje. Ne želiš — ✕ ili samo ignoriši.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteran-izviđač „Sova\" nudi zadatak. Y — prihvati (N — odbij). Idi do oznake ★, ukloni obezbeđenje i stoj kraj pilota 3 s — pridružiće se tvom odredu.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Front je stao — štab nudi preokret. Y — prihvati. Drži relej 8 s bez neprijatelja u blizini: neprijateljska mapa je vidljiva 60 s. Generator — neprijateljske kupole ćute 2 min. U Strateg režimu — „Zadaj odredu\". Neprijatelj to takođe ume: prati ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Svoji traže pomoć: kartica „MOLBA\" i oznaka ✋. Uništi neprijatelje kraj pritisnutog odreda — dobićeš nagradu. ✕ — preskoči.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Heroj „Sova\" nudi zadatak — dodirni „Prihvati\". Idi do ★, ukloni obezbeđenje, stoj kraj pilota.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Front je stao — dodirni „Prihvati\" i drži relej 8 s: neprijateljska mapa će se otvoriti na minut.",
"Pod redeploy from the base: {0} m — through the sky portal":"Prebacivanje kapsulom sa baze: {0} m — kroz nebeski portal",
"Pod away from the base! Hold on — exit over the target.":"Kapsula je krenula sa baze! Držite se — izlazak iznad cilja.",
"Landed at the objective!":"Desant kod cilja!",
"LAUNCH FROM BASE":"LANSIRANJE SA BAZE",
"LANDING":"SLETANJE",
"REDEPLOY":"PREBACIVANJE",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Čelična vuna se zalepila — nagriza oklop −2/s. Stoj 3 s van borbe ili idi do inženjera",
"An engineer brushed the fluff off":"Inženjer je očistio vunu",
"The fluff fell off — armour is safe":"Vuna je otpala — oklop je čitav",
"The firefly swarm scattered by the blast":"Roj krijesnica rasteran eksplozijom",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"ČELIČNA VUNA −2/s · stoj 3 s van borbe ili do inženjera",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Konvoj „Levaka\" je spreman: dva „Šakala\". Drži se blizu — čekaju te",
"The convoy is waiting for you":"Konvoj te čeka",
