"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"konvoj je stigao ({0} od 2)! +2 KP, +150 rude, \"Šakali\" su tvoji",
"The parts are delivered! Thanks, commander.":"Delovi su stigli! Hvala, komandante.",
