"Firefly swarm":"Roj krijesnica",
"Steel dandelions — Steel fluff! It sticks and eats armour!":"Čelični maslačci — Čelična vuna! Zalepi se i nagriza oklop!",
"Fluff in the air — keep out of the meadow and away from the infected!":"Vuna leti — ne ulazi na livadu i ne trljaj se o zaražene!",
"fluff blown away, dormant for 25 s · +0.5 CP":"vuna oduvana, livada miruje 25 s · +0.5 KP",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Moji ljudi voze delove do tačke {0}. Isprati kolonu — putem bi mogla da bude zaseda.",
