"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Tri režima jednim dugmetom: Strelac (sam si u borbi), novi Komandant (vodiš jedan odred, 4 sposobnosti po tipu jedinice) i Strateg. Na telefonu — jednostavan interfejs: manje dugmadi, režimi se otključavaju tokom borbe.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Živi meteor: stene, grebeni, hangar na visoravni, jezera lave, leda i metana, tri biomi, lokalno vreme, nove anomalije i domaća fauna.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Frakcije su postale različite: Roj kopa tunele i regeneriše se, Konzorcijum postavlja barijere i popravlja tehniku. Od 12. minuta — bosovi „Bastion\" i „Reaper\"; u svog možeš da uđeš.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Živi svet: tvoji vojnici traže pomoć preko radija (uz nagradu), heroji daju zadatke, kad front zastane — operacija „Prelom borbe\". Kapsule, sanduci i udari polaze iz baze kroz nebeski portal.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Brže (kadar do 2 puta jeftiniji), gamepad u svim režimima, raspored za tablet, enciklopedija svega u igri, režim utisaka — beleška sa snimkom ekrana jednim tasterom.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Svi novi tekstovi prevedeni su na uzbečki, tadžički, kineski, španski, portugalski i hebrejski. Robo-ninđa i radio iz v7.9 su na mestu; v7.9 je u meniju „🕘 Verzija igre\".",
"New in v8.15":"Novo u v8.15",
"NEW IN v8.15":"NOVO U v8.15",
